head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > tooltipShowAlways]<br/>tooltipDisplay=true 일때 Cell 값 잘림과 관계없이 항상 툴팁을 표시할지 설정합니다.",
    "validation" : [
        "true 설정 시, Cell 영역에 마우스 오버 시 항상 Cell 값을 툴팁으로 표시합니다.",
        "false 설정 시, Cell 값이 모두 표시되지 않을때만(잘림 시) Cell 값을 툴팁으로 표시합니다.",
        "미설정 시, Cell 값이 모두 표시되지 않을때만(잘림 시) Cell 값을 툴팁으로 표시합니다.",
        "true 설정 시, tooltipShowAlwaysColumns 속성 설정은 무의미합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con_tooltipShowAlways 초기값 보관 (true 설정 케이스로 시작)
    scwin.gVar = { "cTooltipShowAlways": "true" };

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - tooltipShowAlways 검증용 커스텀 GridView 를 인라인 정의로 생성한다.
//  - 고정 전제 : tooltipDisplay=true (tooltipShowAlways 는 tooltipDisplay=true 전제에서만 동작)
//  - Body 컬럼 구성
//      col_short  : 짧은(미잘림) 값 text  -> true 면 잘리지 않아도 항상 툴팁 표시 / false·미설정이면 미표시(잘림 아님)
//      col_long   : 긴(잘림) 값 text      -> showAlways 와 무관하게 잘림 시 표시(대비용)
//  - @spec(고유) : tooltipShowAlways=true 이면 tooltipShowAlwaysColumns 설정은 무의미
//      true 케이스에서 tooltipShowAlwaysColumns="col_long" 만 지정해도(col_short 미지정)
//      tooltipShowAlways=true 가 우선하여 col_short(짧은 값)도 항상 툴팁이 표시됨을 시연.
scwin.comp_init = async function () {
    // con 현재값 반영 (Target 재생성 버튼이 comp_init 재호출)
    scwin.gVar.cTooltipShowAlways = con_tooltipShowAlways.getValue();   // "true" / "false" / "" (미설정)

    // 동적 생성용 네임스페이스 (페이지 scope 에서 공통 strNameSpace 가 비어있을 수 있어 로컬 정의)
    let ns = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    let showMsg = (scwin.gVar.cTooltipShowAlways === "") ? "미설정(기본 false)" : scwin.gVar.cTooltipShowAlways;
    $c.gcm.createLabel('label="[전제] tooltipDisplay=true 고정. tooltipShowAlways=' + showMsg + ' / tooltipShowAlwaysColumns=(col_long) 지정.\n[절차] 짧은(미잘림) 값 컬럼(지역) Cell 에 마우스를 오버하여 툴팁을 표시한 뒤 해당 Cell 을 클릭하면 표시된 툴팁 정보가 출력됩니다.\n[확인] true: 잘리지 않아도 짧은 값 Cell 에 항상 툴팁 표시(ShowAlwaysColumns 에 col_short 미지정이어도 표시 -> ShowAlwaysColumns 무의미). false/미설정: 짧은 값은 미표시, 긴 값(주소)은 잘림 시에만 표시."', '', 'label1');

    // dataList 생성 ($p.data.create 로 생성)
    let dlt = '<w2:dataList ' + ns + ' baseNode="list" id="dlt_bind" repeatNode="map">';
    dlt += '<w2:columnInfo>';
    dlt += '<w2:column dataType="text" id="col_short" name="col_short"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_long" name="col_long"></w2:column>';
    dlt += '</w2:columnInfo>';
    dlt += '<w2:data use="true"></w2:data>';
    dlt += '</w2:dataList>';
    $p.data.create(dlt);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDC[arrDC.length - 1];
    scwin.dlt_bind.setJSON([
        { "col_short": "서울", "col_long": "서울특별시 강남구 테헤란로 152 강남파이낸스센터 23층" },
        { "col_short": "부산", "col_long": "부산광역시 해운대구 센텀중앙로 79 센텀사이언스파크 18층" }
    ], false);

    // tooltipShowAlways : con 값에 따라 설정/미설정 (미설정 시 속성 자체를 제외하여 기본값 false 동작 확인)
    let showAttr = (scwin.gVar.cTooltipShowAlways === "") ? "" : 'tooltipShowAlways="' + scwin.gVar.cTooltipShowAlways + '" ';

    // @spec(고유) 시연 : tooltipShowAlwaysColumns 는 col_long 만 지정 (col_short 미지정).
    //  - true 면 tooltipShowAlways 가 우선하여 col_short 도 항상 표시 -> ShowAlwaysColumns 무의미.
    let showColsAttr = 'tooltipShowAlwaysColumns="col_long" ';

    // 커스텀 GridView 인라인 정의 (tooltipDisplay=true 고정, 좁은 폭으로 긴 값 잘림 유도)
    let strTarget = '<w2:gridView ' + ns + ' tooltipDisplay="true" ' + showAttr + showColsAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" inputType="text" id="col_short" value="지역"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="col_long" value="주소"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="80" inputType="text" id="col_short" dataList="col_short"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="col_long" dataList="col_long"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="80" inputType="text" id="ft_short" value="소계"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="ft_long" value="합계 1,234,567,890 원 (전 영업점 기준)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    let grp_comp = document.querySelector('.tc_group_basic');
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 클릭 시 현재 표시된 툴팁 정보를 return 영역에 출력하기 위한 클릭 리스너 설치
    scwin.attachTooltipClick();
}



// Body Cell 클릭 시 "현재 표시된" 툴팁 정보를 return 영역에 출력
//  - 셀에 마우스를 오버해 툴팁(Cell 값)이 표시된 상태에서 그 영역을 클릭하면 호출된다.
//  - 타이밍 주의 : 엔진은 셀 클릭의 기본/버블 처리 단계에서 hover 툴팁을 닫는다(display:none).
//    따라서 클릭의 "캡처(capture) 단계" 리스너로 잡아야 툴팁이 아직 살아있어 정상 출력된다.
//  - 리스너를 그리드 DOM 엘리먼트에 걸어 Cell 클릭을 커버한다.
//  - 마우스오버만 해서는 출력되지 않으며, 클릭 시점에 현재 hover 로 표시된 툴팁 값이 캡처된다.
scwin.attachTooltipClick = function () {
    let gridEl = scwin.target1.getElement ? scwin.target1.getElement() : document.getElementById(scwin.target1.getID());
    if (!gridEl) { return; }
    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }
    scwin.tooltipClickFn = function () { $c.gcm.getTooltipInfo(wf_body_bottom); };
    scwin.tooltipClickEl = gridEl;
    gridEl.addEventListener("click", scwin.tooltipClickFn, true);
};
